To send only the latest message plus the chat ID to your server, use the `prepareSendMessagesRequest` option in the `DefaultChatTransport` configuration. This function lets you transform the request body before it's sent.

Here's how to implement it:

```tsx
import { useChat } from '@ai-sdk/react';
import { DefaultChatTransport } from 'ai';

const { messages, sendMessage } = useChat({
  transport: new DefaultChatTransport({
    api: '/api/chat',
    prepareSendMessagesRequest: ({ id, messages }) => {
      return {
        body: {
          id, // chat ID
          message: messages[messages.length - 1], // only the last message
        },
      };
    },
  }),
});
```

On your server, you'll need to:
1. Receive the chat ID and last message
2. Load the previous messages from storage
3. Append the new message to the history
4. Process the full message history

```tsx
import { convertToModelMessages, createUIMessageStreamResponse, toUIMessageStream } from 'ai';

export async function POST(req: Request) {
  const { id, message } = await req.json();

  // Load previous messages from storage
  const previousMessages = await loadChat(id);

  // Process full message history
  const result = streamText({
    model: yourModel,
    messages: await convertToModelMessages([...previousMessages, message]),
  });

  return createUIMessageStreamResponse({
    stream: toUIMessageStream({
      stream: result.stream,
      originalMessages: [...previousMessages, message],
      onEnd: ({ messages }) => {
        saveChat({ chatId: id, messages });
      },
    }),
  });
}
```

