import { generateText, Output } from 'ai';
import { z } from 'zod';

const { output } = await generateText({
  model: yourModel,
  output: Output.array({
    element: z.object({
      // your element schema here
    }),
    minItems: 5,
    maxItems: 5, // same value enforces exact count
  }),
  prompt: 'Generate exactly 5 items.',
});
```

