To unit test a function that calls `generateText` without using a real model, use the `MockLanguageModelV4` from `ai/test` to mock the model's behavior. Here's a concise example:

```ts
import { generateText } from 'ai';
import { MockLanguageModelV4 } from 'ai/test';

async function myFunction() {
  return generateText({
    model: new MockLanguageModelV4({
      doGenerate: async () => ({
        content: [{ type: 'text', text: 'Mocked response' }],
        finishReason: { unified: 'stop', raw: undefined },
        usage: {
          inputTokens: { total: 10, noCache: 10 },
          outputTokens: { total: 20, text: 20 },
        },
        warnings: [],
      }),
    }),
    prompt: 'Test prompt',
  });
}

// In your test:
const result = await myFunction();
expect(result.text).toBe('Mocked response');
```

Key points:
- Import `MockLanguageModelV4` from `ai/test` [2]
- Pass it as the `model` to `generateText` [1]
- Control the mock's output via the `doGenerate` function [1][2]
- The mock returns deterministic, testable responses without calling a real model [2]

```ts
import { describe, it, expect } from 'vitest';
import { streamText, simulateReadableStream } from 'ai';
import { MockLanguageModelV4 } from 'ai/test';

async function generateGreeting(prompt: string): Promise<string> {
  const result = streamText({
    model: new MockLanguageModelV4({
      doStream: async () => ({
        stream: simulateReadableStream({
          chunks: [
            { type: 'text-start', id: 'text-1' },
            { type: 'text-delta', id: 'text-1', delta: 'Hello' },
            { type: 'text-delta', id: 'text-1', delta: ' world' },
            { type: 'text-delta', id: 'text-1', delta: '!' },
            { type: 'text-end', id: 'text-1' },
            {
              type: 'finish',
              finishReason: { unified: 'stop', raw: undefined },
              logprobs: undefined,
              usage: {
                inputTokens: {
                  total: 3,
                  noCache: 3,
                  cacheRead: undefined,
                  cacheWrite: undefined,
                },
                outputTokens: {
                  total: 10,
                  text: 10,
                  reasoning: undefined,
                },
              },
            },
          ],
        }),
      }),
    }),
    prompt,
  });

  let fullText = '';
  for await (const delta of result.textStream) {
    fullText += delta;
  }

  return fullText;
}

describe('generateGreeting', () => {
  it('should stream "Hello world!"', async () => {
    const result = await generateGreeting('Say hello');
    expect(result).toBe('Hello world!');
  });
});
```

